const ifs = gE.nodes.filter(n=>n.kind==='if_statement');
console.log('E if structured edges from if', gE.edges.filter(e=>ifs.some(i=>i.id===e.from)));

// Case F: empty then with else
const gF = await G(`function run(f){ if(f){ } else { e() } d() }\n`);
console.log('F empty then', gF.edges.filter(e=>e.type.startsWith('CFG')).map(e=>({t:e.type, fl:gF.nodes.find(n=>n.id===e.from)?.range?.start?.line, tl:gF.nodes.find(n=>n.id===e.to)?.range?.start?.line})));

// Case G: shadowing
const tG = await T(`function readInput(){} function send(v){}
function run(){ let value=readInput(); { let value=1; } send(value) }\n`);
console.log('G shadowing (non-goal) paths', tG.payload.length);

