// Case O: multi-statement branch tails
const gO = await G(`function run(f){ if(f){ a(); b() } else { c(); d() } e() }\n`);
console.log('O multi tail', gO.edges.filter(e=>e.type.startsWith('CFG')).map(e=>({t:e.type, fl:gO.nodes.find(n=>n.id===e.from)?.range?.start?.line, tl:gO.nodes.find(n=>n.id===e.to)?.range?.start?.line})));

// Case P: return in branch
const gP = await G(`function run(f){ if(f){ return a() } else { b() } c() }\n`);
console.log('P return branch', gP.edges.filter(e=>e.type.startsWith('CFG')).map(e=>({t:e.type, fl:gP.nodes.find(n=>n.id===e.from)?.range?.start?.line, tl:gP.nodes.find(n=>n.id===e.to)?.range?.start?.line||e.to.slice(-8)})));

// Case Q: provenance
const tQ = await T(`function readInput(){} function send(v){} function run(){ send(readInput()) }\n`);
console.log('Q meaning', tQ.provenance.meaning, 'scope cpg', (await setup(`function f(){}`).cpg.invoke('cpg.build',{path:'src/a.js'},{root:setup(`function f(){}`).root, budgetTokens:1000}).catch(()=>null)));
const fQ = setup(`function f(){ let a=1; return a }\n`);
const rQ = await fQ.cpg.invoke('cpg.build',{path:'src/a.js'},fQ.ctx);
console.log('Q cpg provenance', rQ.provenance);

// Case R: reverify + resume tiny budget
const fR = setup(`function readInput(){} function send(v){} function run(){ let a=readInput(); send(a) }\n`);
