console.log('Q meaning', tQ.provenance.meaning, 'scope cpg', (await setup(`function f(){}`).cpg.invoke('cpg.build',{path:'src/a.js'},{root:setup(`function f(){}`).root, budgetTokens:1000}).catch(()=>null)));
const fQ = setup(`function f(){ let a=1; return a }\n`);
const rQ = await fQ.cpg.invoke('cpg.build',{path:'src/a.js'},fQ.ctx);
console.log('Q cpg provenance', rQ.provenance);

// Case R: reverify + resume tiny budget
const fR = setup(`function readInput(){} function send(v){} function run(){ let a=readInput(); send(a) }\n`);
const built = await fR.cpg.invoke('cpg.build',{path:'src/a.js'},{...fR.ctx, budgetTokens: 5});
console.log('R status', built.status, 'cursor', !!built.cursor, 'payload', built.payload.length);
if (built.cursor) {
  const resumed = await fR.cpg.resume(built.refs[0], built.cursor, {...fR.ctx, budgetTokens: 10000});
  console.log('R resume', resumed.status, resumed.payload.length, resumed.provenance);
}
const rev = await fR.cpg.reverify({provenance: built.provenance}, {path:'src/a.js'}, fR.ctx);
console.log('R reverify', rev);

// Case S: if ( ( false ) )
const gS = await G(`function run(){ if((false)){ dead() } live() }\n`);
console.log('S paren false', gS.nodes.filter(n=>n.type==='statement').map(s=>({l:s.range.start.line,k:s.kind,r:s.cfgReachable})), gS.edges.filter(e=>e.type==='CFG_TRUE'||e.type==='CFG_FALSE'));

// Case T: assignment from nested identifier only direct
const gT = await G(`function run(){ let a=b+c; let d=e }\n`);
console.log('T assign edges', gT.edges.filter(e=>e.type==='ASSIGNED_FROM').length);

// Case U: ceiling exact
try {
  const fU = setup(`function send(v){} function run(a){ let b=a; let c=b; send(c) }\n`, {maxReachDefPairs:2});
  await fU.cpg.invoke('cpg.build',{path:'src/a.js'},fU.ctx);
  console.log('U ceiling2 ok?');
} catch(e) { console.log('U ceiling2', e.code); }

// Case V: for-loop atomic
const tV = await T(`function readInput(){} function send(v){}
function run(){ let value; for(;;){ value=readInput(); break } send(value) }\n`);
console.log('V for atomic taint', tV.payload.length);

// Case W: ternary non-expand
const gW = await G(`function run(f){ let x = f ? a() : b(); c() }\n`);
console.log('W ternary cfg types', [...new Set(gW.edges.map(e=>e.type))]);

// Case X: else-if chain of 3
const gX = await G(`function run(f){
  if(f===1){ a() }
  else if(f===2){ b() }
  else if(f===3){ c() }
  else { d() }
  e()
}\n`);
const ifX = gX.nodes.filter(n=>n.kind==='if_statement').sort((a,b)=>a.range.start.line-b.range.start.line);
console.log('X elseif chain', ifX.map(i=>({l:i.range.start.line,r:i.cfgReachable})), gX.edges.filter(e=>e.type==='CFG_FALSE'||e.type==='CFG_TRUE').map(e=>({t:e.type, fl:gX.nodes.find(n=>n.id===e.from)?.range.start.line, tl:gX.nodes.find(n=>n.id===e.to)?.range?.start?.line})));

// Case Y: switch atomic
const tY = await T(`function readInput(){} function send(v){}
function run(f){ let value; switch(f){ case 1: value=readInput(); break; default: value=1 } send(value) }\n`);
console.log('Y switch atomic taint', tY.payload.length);

// Case Z: delta impact meaning
import { AtlasCpgDelta } from './impl/src/index.mjs';
const beforeRoot = mkdtempSync(join(tmpdir(),'b-')); const afterRoot = mkdtempSync(join(tmpdir(),'c-')); const dart = mkdtempSync(join(tmpdir(),'d-'));
mkdirSync(join(beforeRoot,'src'),{recursive:true}); mkdirSync(join(afterRoot,'src'),{recursive:true});
writeFileSync(join(beforeRoot,'src/a.js'), `function readInput(){} function send(v){} function run(f){ let v=readInput(); if(f){ v=1 } send(v) }\n`);
writeFileSync(join(afterRoot,'src/a.js'), `function readInput(){} function send(v){} function run(f){ let v=readInput(); if(f){ v=2 } send(v) }\n`);
const delta = new AtlasCpgDelta({ artifactRoot: dart, maxSourceBytes:64*1024, maxGraphBytes:512*1024, maxDeltaBytes:512*1024, maxImpactDepth:8, maxReachDefPairs:128 });
const dres = await delta.invoke('cpg.delta', { beforePath:'src/a.js', afterPath:'src/a.js', impactDepth:4 }, { beforeRoot, afterRoot, budgetTokens:10000 });
console.log('Z delta', dres.provenance.impactMeaning, dres.summary, dres.payload.filter(p=>p.recordType==='impact').slice(0,5));
