cd /private/tmp/baton-cpg-correction-review.oZnxIH/.baton/wt/grok-cpg-impl-review-45 && node --input-type=module <<'EOF'
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint } from './impl/src/index.mjs';

function setup(source, opts={}) {
  const root = mkdtempSync(join(tmpdir(), 'r-'));
  const artifacts = mkdtempSync(join(tmpdir(), 'a-'));
  mkdirSync(join(root,'src'),{recursive:true});
  writeFileSync(join(root,'src/a.js'), source);
  const common = { maxSourceBytes: 64*1024, maxReachDefPairs: 256, ...opts };
  const cpg = new AtlasCpgSlice({ artifactRoot: join(artifacts,'cpg'), maxArtifactBytes: 512*1024, ...common });
  const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts,'taint'), maxGraphBytes: 512*1024, maxResultBytes: 512*1024, maxDepth: 24, maxPaths: 32, ...common });
  return { root, cpg, taint, ctx: { root, budgetTokens: 20000 } };
}
async function G(source) {
  const f = setup(source);
  const r = await f.cpg.invoke('cpg.build', { path: 'src/a.js' }, f.ctx);
  return JSON.parse(readFileSync(r.refs[0].path,'utf8'));
}
async function T(source, policy={}) {
  const f = setup(source);
  return f.taint.invoke('cpg.taint', { path:'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20, ...policy }, f.ctx);
}

// Case A: nested ifs both branches join
const g1 = await G(`function run(a,b){
  if (a) {
    if (b) { left() } else { mid() }
  } else {
    right()
  }
  done()
}\n`);
const stmts = g1.nodes.filter(n=>n.type==='statement');
const byLine = Object.fromEntries(stmts.map(s=>[s.range.start.line, s]));
console.log('A nested joins cfg:', {
  lines: stmts.map(s=>({line:s.range.start.line, kind:s.kind, reach:s.cfgReachable})),
  trueFalse: g1.edges.filter(e=>['CFG_TRUE','CFG_FALSE','CFG_NEXT','CFG_EXIT'].includes(e.type)).map(e=>({t:e.type, from: stmts.find(s=>s.id===e.from)?.range.start.line ?? e.from.slice(-20), to: stmts.find(s=>s.id===e.to)?.range.start.line ?? e.to.slice(-20)}))
});

// Case B: if(true) dead else
const g2 = await G(`function run(){ if(true){ live() } else { dead() } after() }\n`);
console.log('B literal true:', g2.nodes.filter(n=>n.type==='statement').map(s=>({line:s.range.start.line, text:s.kind, reach:s.cfgReachable, kind:s.kind})));
console.log('B edges', g2.edges.filter(e=>e.type.startsWith('CFG')).map(e=>({t:e.type,from:g2.nodes.find(n=>n.id===e.from)?.range?.start?.line, to:g2.nodes.find(n=>n.id===e.to)?.range?.start?.line || e.to.slice(-12)})));

// Case C: try with if alternate defs may-reach?
const tC = await T(`function readInput(){} function safe(){} function send(v){}
function run(flag){ let value; try { if(flag){ value=readInput() } else { value=safe() } } catch(e){} send(value) }\n`);
console.log('C try+if may taint paths', tC.payload.length, tC.payload[0]?.edgeTypes);

// Case D: only safe in else of try if - order last-wins?
const tD1 = await T(`function readInput(){} function safe(){} function send(v){}
function run(flag){ let value=safe(); try { if(flag){ value=readInput() } } catch(e){} send(value) }\n`);
const tD2 = await T(`function readInput(){} function safe(){} function send(v){}
function run(flag){ let value=readInput(); try { if(flag){ value=safe() } } catch(e){} send(value) }\n`);
console.log('D1 pre-safe try if-source paths', tD1.payload.length);
console.log('D2 pre-source try if-safe paths', tD2.payload.length);

// Case E: unbraced if atomic
const gE = await G(`function run(flag){ if(flag) left(); else right(); done() }\n`);
console.log('E unbraced ifs', gE.edges.filter(e=>e.type.startsWith('CFG')).map(e=>({t:e.type, fromKind:gE.nodes.find(n=>n.id===e.from)?.kind||gE.nodes.find(n=>n.id===e.from)?.type, toKind:gE.nodes.find(n=>n.id===e.to)?.kind||gE.nodes.find(n=>n.id===e.to)?.type})));
const ifs = gE.nodes.filter(n=>n.kind==='if_statement');
console.log('E if structured edges from if', gE.edges.filter(e=>ifs.some(i=>i.id===e.from)));

// Case F: empty then with else
const gF = await G(`function run(f){ if(f){ } else { e() } d() }\n`);
console.log('F empty then', gF.edges.filter(e=>e.type.startsWith('CFG')).map(e=>({t:e.type, fl:gF.nodes.find(n=>n.id===e.from)?.range?.start?.line, tl:gF.nodes.find(n=>n.id===e.to)?.range?.start?.line})));

// Case G: shadowing
const tG = await T(`function readInput(){} function send(v){}
function run(){ let value=readInput(); { let value=1; } send(value) }\n`);
console.log('G shadowing (non-goal) paths', tG.payload.length);

// Case H: while false body still taints?
const tH = await T(`function readInput(){} function send(v){}
function run(){ let value; while(false){ value=readInput() } send(value) }\n`);
console.log('H while false atomic taint', tH.payload.length);

// Case I: else-if middle only
const tI = await T(`function readInput(){} function safe(){} function send(v){}
function run(flag){
  let value=safe()
  if(flag===1){ value=safe() }
  else if(flag===2){ value=readInput() }
  else { value=safe() }
  send(value)
}\n`);
console.log('I else-if middle', tI.payload.length);

// Case J: if false with source before
const tJ = await T(`function readInput(){} function send(v){}
function run(){ let value=readInput(); if(false){ value=1 } send(value) }\n`);
console.log('J false branch kill not applied on true-only? paths', tJ.payload.length);

// Case K: both arms define - join may
const gK = await G(`function run(f){ let x; if(f){ x=1 } else { x=2 } use(x) }\n`);
const defs = gK.nodes.filter(n=>n.type==='identifier'&&n.role==='definition'&&n.name==='x');
const refs = gK.nodes.filter(n=>n.type==='identifier'&&n.role==='reference'&&n.name==='x');
const rds = gK.edges.filter(e=>e.type==='REACHING_DEF'&&refs.some(r=>r.id===e.to));
console.log('K join may-defs', { defs: defs.length, refs: refs.map(r=>r.range), rdCount: rds.length, fromRoles: rds.map(e=>gK.nodes.find(n=>n.id===e.from)?.range) });

// Case L: statement anchors on calls
const gL = await G(`function run(){ if(false){ send(readInput()) } ok() }\n`);
console.log('L dead calls', gL.nodes.filter(n=>n.type==='call').map(c=>({name:c.calleeName, reach:c.cfgReachable, anchor:c.cfgAnchor!=null})));

// Case M: ARGUMENT_TO nested only direct
const gM = await G(`function run(){ send(sanitize(readInput())) }\n`);
console.log('M arg edges', gM.edges.filter(e=>e.type==='ARGUMENT_TO'||e.type==='ASSIGNED_FROM').map(e=>({t:e.type, from:gM.nodes.find(n=>n.id===e.from)?.calleeName||gM.nodes.find(n=>n.id===e.from)?.name, to:gM.nodes.find(n=>n.id===e.to)?.calleeName||gM.nodes.find(n=>n.id===e.to)?.name})));

// Case N: if without else false goes to join
const gN = await G(`function run(f){ if(f){ a() } b() }\n`);
console.log('N no else', gN.edges.filter(e=>e.type.startsWith('CFG')).map(e=>({t:e.type, fl:gN.nodes.find(n=>n.id===e.from)?.range?.start?.line, tl:gN.nodes.find(n=>n.id===e.to)?.range?.start?.line})));

