cd /private/tmp/baton-cpg-correction-review.oZnxIH/.baton/wt/grok-cpg-impl-review-45 && node --input-type=module <<'EOF'
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint } from './impl/src/index.mjs';

function setup(source) {
  const root = mkdtempSync(join(tmpdir(), 'r-'));
  const artifacts = mkdtempSync(join(tmpdir(), 'a-'));
  mkdirSync(join(root,'src'),{recursive:true});
  writeFileSync(join(root,'src/a.js'), source);
  const common = { maxSourceBytes: 64*1024, maxReachDefPairs: 256 };
  const cpg = new AtlasCpgSlice({ artifactRoot: join(artifacts,'cpg'), maxArtifactBytes: 512*1024, ...common });
  const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts,'taint'), maxGraphBytes: 512*1024, maxResultBytes: 512*1024, maxDepth: 24, maxPaths: 32, ...common });
  return { root, cpg, taint, ctx: { root, budgetTokens: 20000 } };
}
async function analyze(label, source) {
  const f = setup(source);
  const r = await f.cpg.invoke('cpg.build', { path: 'src/a.js' }, f.ctx);
  const g = JSON.parse(readFileSync(r.refs[0].path,'utf8'));
  const t = await f.taint.invoke('cpg.taint', { path:'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20 }, f.ctx);
  const calls = g.nodes.filter(n=>n.type==='call' && ['readInput','send'].includes(n.calleeName)).map(c=>({name:c.calleeName, reach:c.cfgReachable, anchor: !!c.cfgAnchor, stmt: c.statement?.slice?.(-30)}));
  const rds = g.edges.filter(e=>e.type==='REACHING_DEF').length;
  console.log(label, { paths: t.payload.length, calls, rds, edgeTypes: t.payload[0]?.edgeTypes });
}

await analyze('braced if in try', `function readInput(){} function send(v){}
function run(flag){ let value; try { if(flag){ value=readInput() } } catch(e){} send(value) }\n`);

await analyze('unbraced if in try', `function readInput(){} function send(v){}
function run(flag){ let value; try { if(flag) value=readInput() } catch(e){} send(value) }\n`);

await analyze('braced if only (control)', `function readInput(){} function send(v){}
function run(flag){ let value; if(flag){ value=readInput() } send(value) }\n`);

await analyze('while braced body', `function readInput(){} function send(v){}
function run(){ let value; while(x){ value=readInput() } send(value) }\n`);

await analyze('while with nested braced if', `function readInput(){} function send(v){}
function run(flag){ let value; while(x){ if(flag){ value=readInput() } } send(value) }\n`);

await analyze('for with nested braced if', `function readInput(){} function send(v){}
function run(flag){ let value; for(;;){ if(flag){ value=readInput() } break } send(value) }\n`);

// gen last-wins at atomic parent
await analyze('switch two assigns', `function readInput(){} function send(v){}
