  // CFG edges involving if
  cfg: g.edges.filter(e=>e.type.startsWith('CFG') && (e.from===ifs[0]?.id || e.to===ifs[0]?.id || e.from===tries[0]?.id || e.to===tries[0]?.id)).map(e=>({t:e.type, from:g.nodes.find(n=>n.id===e.from)?.kind||g.nodes.find(n=>n.id===e.from)?.type, to:g.nodes.find(n=>n.id===e.to)?.kind||g.nodes.find(n=>n.id===e.to)?.type}))
});

