const f2 = setup(`function readInput(){} function send(v){}
function run(ok){
  let value
  try {
    if (ok) value = readInput()
  } catch (e) {}
  send(value)
}\n`);
const t2 = await f2.taint.invoke('cpg.taint',{path:'src/a.js',sourceNames:['readInput'],sinkNames:['send'],depth:20},f2.ctx);
console.log('unbraced paths', t2.payload.length);
EOF

